/**
 * @description Desk settings
*/
export type DeskSettings = {
    /**
     * @description Whether the daemon\'s REMB-driven adaptive bitrate cap is active\nfor this connection. Defaults to `true`. Session-scoped state:\nit takes effect per connection (initialised from the offer\'s\nsession settings, live-toggled via `ApplyRemoteSessionSettings` for the\noriginating connection only) and is not persisted server-side —\nthe browser keeps the user\'s preference. Distinct from the\nbrowser-side adaptive *quality* loop: the cap only trims\nbitrate spikes, quality stays untouched.
     * @default true
     * @type boolean | undefined
    */
    adaptive_bitrate?: boolean;
    /**
     * @description Enable adaptive web page resolution
     * @default false
     * @type boolean | undefined
    */
    adaptive_web_page_resolution?: boolean;
    /**
     * @description Selected audio capture device
     * @type string,null
    */
    audio_capture?: string | null;
    /**
     * @default null
    */
    audio_device?: (null | SelectedAudioDevice);
    /**
     * @description Audio encoder name, None for auto detection
     * @type string,null
    */
    audio_encoder?: string | null;
    /**
     * @default null
    */
    av1_encoder?: (null | Av1EncoderSettings);
    /**
     * @description Display name
     * @type string,null
    */
    display_name?: string | null;
    /**
     * @description Enable D3D debug mode
     * @default false
     * @type boolean | undefined
    */
    enable_d3d_debug?: boolean;
    /**
     * @description Whether the encoder may honour `ImageInfo::get_dirty_rects` to only\nre-convert changed regions of the BGRA frame into the persistent YUV\nbuffer. Defaults to `true` (the optimisation is on). Setting it to\n`false` forces every captured frame through a full BGRA→YUV\nconversion — useful as a kill-switch when partial updates surface\nrendering artefacts (e.g. transient black bars on animation-heavy\ncontent).
     * @default true
     * @type boolean | undefined
    */
    enable_dirty_rect?: boolean;
    /**
     * @default null
    */
    h264_encoder?: (null | H264EncoderSettings);
    /**
     * @description Selected image capture device
     * @type string,null
    */
    image_capture?: string | null;
    /**
     * @default null
    */
    opus_encoder?: (null | OpusEncoderSettings);
    /**
     * @default [object Object]
    */
    private_screen?: PrivateScreenSettings;
    /**
     * @description Enable mouse display on the screen
     * @default true
     * @type boolean | undefined
    */
    show_mouse?: boolean;
    /**
     * @description GDI device name of the capture target (`\\\\.\\DISPLAYn`).\nEmpty string means \"no display selected yet\" — the browser\nmust surface a chooser before starting media. Selection is by\nname (instead of enumeration index) because:\n1. DXGI and WGC backends walk different enumerations\n   (`IDXGIAdapter::EnumOutputs` vs `EnumDisplayMonitors`), but\n   both expose the same GDI device name — so a name-based key\n   is the only stable cross-backend addressing.\n2. Display hot-plug (attach / detach / IDD bring-up) reorders\n   the enumeration, so an index saved in settings would drift\n   onto the wrong monitor across reboots.
     * @default ""
     * @type string | undefined
    */
    video_device_name?: string;
    /**
     * @description Video encoder name, None for auto detection
     * @type string,null
    */
    video_encoder?: string | null;
    /**
     * @description Video frame rate (e.g., 30 fps)
     * @minLength 0
     * @default 60
     * @type integer | undefined, int32
    */
    video_fps?: number;
    /**
     * @description Video encode quality, 0-63, lower is better. Default is 22.
     * @minLength 0
     * @default 22
     * @type integer | undefined, int32
    */
    video_quality?: number;
    /**
     * @default null
    */
    vp8_encoder?: (null | VpxEncoderSettings);
    /**
     * @default null
    */
    vp9_encoder?: (null | VpxEncoderSettings);
    /**
     * @description Wayland control mode: portal/uinput/none
     * @type string,null
    */
    wayland_control_mode?: string | null;
    /**
     * @default null
    */
    x264_encoder?: (null | X264EncoderSettings);
};

