/**
 * @description RequestRemoteModel is used to request remote access.\nweb browser -> signaling server -> desk server
*/
export type RequestRemoteModel = {
    /**
     * @description Browser-writable, **untrusted** selector naming which grant session this\nrequest redeems (set after redeeming a device / support code). It only\n*selects* a grant; the authorization fact — whether it is honored and what\ncapability ceiling it carries — is decided server-side by looking the grant\nup and checking the caller\'s server-resolved principal, and is stamped into\nthe trusted [`crate::model::request_remote_authz::RequestRemoteAuthz`]. A browser\npresenting someone else\'s `grant_session_id` is rejected at that principal\ncheck. `None` on a normal owner/org request.
     * @type string,null
    */
    grant_session_id?: string | null;
    /**
     * @description ICE servers, the value comes from signaling server
     * @type array | undefined
    */
    ice_servers?: LcxlRTCIceServer[];
    /**
     * @description Browser-supplied organization-context selector. It never grants access or\nchooses a payer by itself: a central manager must validate membership and\nthe organization\'s target-device grant before using it. Standalone signal\nservers ignore it. `None` is personal context.
     * @type integer,null, int32
    */
    org_id?: number | null;
    /**
     * @description Required session purpose hint. It only controls resource preparation and\nnever grants a capability.
     * @type string
    */
    purpose: RemoteSessionPurpose;
    /**
     * @type string,null
    */
    requested_wayland_control_mode?: string | null;
    /**
     * @description Opaque daemon-issued session target. Omit only when the requested\ncapability has exactly one ready worker, in which case the host binds it\nautomatically. With multiple candidates the host fails closed and\nreturns the selectable target descriptors.
     * @type string,null
    */
    session_target_id?: string | null;
};

