export type RestResponseVirtualDisplaySettings = {
    /**
     * @type integer, int32
    */
    code: number;
    /**
     * @description Virtual display (Windows IDD) settings. Pulled out into its own\nsection because the knob is system-level (only the\n`ServiceDaemon` startup mode acts on it, and changing it requires\nthe `LcxlVirtualDisplay` driver to already be staged) — not a\nper-session capture setting. Kept as a struct rather than a bare\n`bool` so future fields (e.g. exclusive-mode toggle, pre-detach\nprompt duration) slot in without another schema migration.
     * @type object | undefined
    */
    data?: {
        /**
         * @description Browser-side trailing-edge debounce window (ms) for the adaptive\nresolution hook. Resize events within this window reset the\ntimer; the send fires only after the wrapper has been stable for\nthis many ms. Sourced from `config.toml`; ferried to the browser\nvia `RemoteAccessInitializedData::adaptive_resolution`.
         * @minLength 0
         * @default 5000
         * @type integer | undefined, int64
        */
        adaptive_debounce_ms?: number;
        /**
         * @description Minimum pixel delta on either axis the browser hook treats as\nsignificant. Below this, both width and height changes are\nskipped to suppress micro-jitter from cursor-driven resize loops.
         * @minLength 0
         * @default 16
         * @type integer | undefined, int32
        */
        adaptive_min_delta_px?: number;
        /**
         * @description Daemon-side minimum interval (ms) between accepted auto\nChangeDisplaySettings requests. `0` is allowed and disables the\ndefense entirely.
         * @minLength 0
         * @default 1000
         * @type integer | undefined, int64
        */
        adaptive_throttle_ms?: number;
        /**
         * @description Whether the daemon should create the Windows IDD virtual\nmonitor at startup. Service-daemon mode only — other startup\nmodes ignore the flag entirely. The `/api/desk/settings/virtual-display`\nPOST endpoint rejects `enabled = true` (with body code\n`PRECONDITION_FAILED`) unless the driver is already staged.
         * @default false
         * @type boolean | undefined
        */
        enabled?: boolean;
        /**
         * @description Exclusive mode: when a remote control session is accepted and\nthe virtual display is attached, the daemon asks the worker to\ndetach all physical displays so Windows migrates existing\nwindows onto the virtual display. Gated on accept_control to\navoid locking the local user out of the UAC / authorization\nsurface. Default off so a fresh install keeps the existing\n\"extend mode\" behavior.
         * @default false
         * @type boolean | undefined
        */
        exclusive?: boolean;
        /**
         * @description Pre-detach prompt window duration (ms) shown on physical\ndisplays before they are detached. Gives the local user time\nto react. `0` skips the prompt entirely.
         * @minLength 0
         * @default 5000
         * @type integer | undefined, int32
        */
        prompt_ms?: number;
    };
    /**
     * @type string,null
    */
    message?: string | null;
    /**
     * @type boolean
    */
    success: boolean;
};

