/**
 * @description System settings for the application. This struct is used to load and save settings from a configuration file.
*/
export type SystemSettings = {
    /**
     * @description Auto start the application on system login
     * @type boolean,null
    */
    auto_start?: boolean | null;
    /**
     * @description Client ID for telemetry
     * @type string,null
    */
    client_id?: string | null;
    /**
     * @description Enable IPv6 support
     * @default true
     * @type boolean | undefined
    */
    enable_ipv6?: boolean;
    /**
     * @description Whether the local shell shows ongoing remote-access status.
     * @default true
     * @type boolean | undefined
    */
    host_access_indicator_enabled?: boolean;
    /**
     * @description listen ipv4 address for the server to bind to
     * @default "0.0.0.0"
     * @type string | undefined
    */
    listen_addr_ipv4?: string;
    /**
     * @description listen ipv6 address for the server to bind to
     * @default "::"
     * @type string | undefined
    */
    listen_addr_ipv6?: string;
    /**
     * @description Local signaling server token, auto-generated and persisted.\nUsed by the local desk server to authenticate with the co-located signaling server.
     * @type string,null
    */
    local_signaling_token?: string | null;
    /**
     * @description Optional locale setting (e.g., \"en\", \"zh-CN\")
     * @type string,null
    */
    locale?: string | null;
    /**
     * @description API Token for connecting to manager\'s signaling server
     * @type string,null
    */
    manager_api_token?: string | null;
    /**
     * @description Whether the host should keep the manager link connected. This is a\nhost-local UI toggle that lets a user disable the manager connection\nwithout clearing `manager_url` / `manager_api_token`, so the address is\nretained for a later re-enable. `None` / `Some(true)` = enabled;\n`Some(false)` = explicitly disabled. Host-local only: no signaling frame\ncan read or write the host\'s system settings.
     * @type boolean,null
    */
    manager_enabled?: boolean | null;
    /**
     * @description Remote manager server url for connecting to an enterprise manager
     * @type string,null
    */
    manager_url?: string | null;
    /**
     * @description port number for the server to bind to
     * @minLength 0
     * @default 8081
     * @type integer | undefined, int32
    */
    port?: number;
    /**
     * @description Whether the host refuses to dial a remote signaling server / manager over\na plaintext scheme (`ws://` / `http://`) when the target resolves to a\n*public* (internet-routable) address. Defaults to `true` (secure): a\npublic plaintext dial would carry the API token and all signaling in the\nclear across untrusted networks. Loopback / private / LAN targets are\nalways reachable over plaintext regardless of this switch (a self-hosted\nsignaling server on a LAN commonly has no TLS), and the cloud-metadata\nhard floor is always blocked. Set to `false` only as a deliberate escape\nhatch for a trusted-network deployment that intentionally runs a public\nendpoint without TLS. A plain `bool` (not `Option`) so an update payload\nthat omits it fails secure to `true`.
     * @default true
     * @type boolean | undefined
    */
    require_secure_signaling?: boolean;
    /**
     * @description Stable cookie signing key for session middleware (hex-encoded).\nAuto-generated and persisted so sessions survive daemon restarts.
     * @type string,null
    */
    session_secret_key?: string | null;
    /**
     * @description Token for authenticating with the remote signaling server
     * @type string,null
    */
    signaling_token?: string | null;
    /**
     * @description Remote signaling server url for connecting to a standalone signaling server
     * @type string,null
    */
    signaling_url?: string | null;
    /**
     * @description Token for authenticating the Tauri IPC WebSocket connection (/ws/tauri_ipc).\nAuto-generated and persisted on first startup.
     * @type string,null
    */
    tauri_ipc_token?: string | null;
    /**
     * @description Telemetry consent status
     * @type boolean,null
    */
    telemetry_consent?: boolean | null;
    /**
     * @description Override for the daemon-side WebRTC ICE `disconnected` timeout\n(the duration without ICE traffic before an agent flips\n`Connected → Disconnected`). `None` means use the built-in\ndefault; see `pc_manager::DEFAULT_DAEMON_ICE_DISCONNECTED_TIMEOUT_SECS`.\n\nLowering it makes the daemon-side cleanup hook fire sooner when\na browser closes the tab, which is what frees the worker\'s DXGI\nduplication for the next session. Lower it too far and a real\nnetwork blip will tear down a healthy session.\n\nNot surfaced in the settings UI yet — edit the config file\ndirectly or rely on the default.
     * @minLength 0
     * @type integer,null, int64
    */
    webrtc_ice_disconnected_timeout_secs?: number | null;
    /**
     * @description Override for the daemon-side WebRTC ICE `failed` timeout (the\nduration in `Disconnected` before an agent flips to `Failed`).\n`None` means use the built-in default; see\n`pc_manager::DEFAULT_DAEMON_ICE_FAILED_TIMEOUT_SECS`.\n\nTogether with `webrtc_ice_disconnected_timeout_secs` this caps\nhow long the daemon waits before reclaiming the\nper-`connection_id` resources. The pair-active signaling-side\n`ConnectionRemoved` notification (when present) bypasses both\ntimeouts and triggers cleanup in milliseconds; this fallback\nonly matters when signaling itself is gone too.\n\nNot surfaced in the settings UI yet — edit the config file\ndirectly or rely on the default.
     * @minLength 0
     * @type integer,null, int64
    */
    webrtc_ice_failed_timeout_secs?: number | null;
    /**
     * @description Number of seconds without a worker heartbeat before the\nwatchdog declares the worker stuck and triggers a restart.\nWorkers send heartbeats every 5s; the default of 30s gives\nroughly 6 missed beats of slack so transient spikes don\'t\ntrigger spurious restarts.
     * @minLength 0
     * @type integer,null, int64
    */
    worker_heartbeat_timeout_secs?: number | null;
    /**
     * @description Whether the daemon should kill+restart a session worker that\nstops sending heartbeats. Defaults to enabled. Set to `false`\nwhen investigating worker hangs so the stuck process stays\nalive long enough to attach a debugger / capture a stack dump.
     * @type boolean,null
    */
    worker_heartbeat_watchdog_enabled?: boolean | null;
};

